using Hyper.Domain.Entities.Integrations; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; namespace Hyper.Infrastructure.Data.Configurations; public sealed class ExternalProductMappingConfiguration:IEntityTypeConfiguration<ExternalProductMapping>{public void Configure(EntityTypeBuilder<ExternalProductMapping>b){b.ToTable("ExternalProductMappings");b.HasKey(x=>x.Id);b.Property(x=>x.ExternalProductId).HasMaxLength(200).IsRequired();b.Property(x=>x.ExternalSku).HasMaxLength(200);b.Property(x=>x.ExternalVariantId).HasMaxLength(200);b.HasIndex(x=>new{x.ConnectionId,x.ExternalProductId,x.ExternalVariantId}).IsUnique();b.HasOne<ExternalIntegrationConnection>().WithMany().HasForeignKey(x=>x.ConnectionId).OnDelete(DeleteBehavior.Cascade);}}
